    var dark = mode === 'dark';
    try {
      localStorage.setItem('theme', dark ? 'dark' : 'light');
    } catch (e) {}
    document.documentElement.classList.toggle('bp4-dark', dark);
    if (document.body) document.body.classList.toggle('bp4-dark', dark);
    refreshLogoSrcs();
    var btn = document.getElementById('astrans-theme-toggle');
    if (btn) btn.textContent = dark ? 'Light mode' : 'Dark mode';
