  function hideStockAuthMarks() {
    // One-shot: hide leftover Bigcapital SVGs by size. Never touch inputs/buttons.
    try {
      document.querySelectorAll('#root svg').forEach(function (svg) {
        if (svg.classList.contains('astrans-stock-hide')) return;
        if (svg.closest('button, a, .bp4-input-group, .bp4-form-group, label, input')) return;
        var r = svg.getBoundingClientRect();
        if (r.width >= 72 && r.height >= 18 && r.height <= 90) {
          svg.classList.add('astrans-stock-hide');
        }
      });
    } catch (e) {}
  }

  function hidePublicSignup() {
    try {
      if (location.pathname.indexOf('/auth/register') === 0) {
        location.replace('/auth/login');
        return;
      }
      document.querySelectorAll('a[href="/auth/register"], a[href="/auth/register/"]').forEach(function (a) {
        var row = a.closest('p') || a.parentElement;
        if (row && row.style) row.style.display = 'none';
        a.style.display = 'none';
      });
    } catch (e) {}
  }

  function isAuthPath() {
    try {
      return location.pathname.indexOf('/auth') === 0;
    } catch (e) {
      return false;
    }
  }

  function teardownAuthChrome() {
    try {
      document.documentElement.classList.remove('astrans-on-auth');
      var title = document.getElementById('astrans-auth-title');
      if (title && title.parentNode) title.parentNode.removeChild(title);
      var chrome = document.getElementById('astrans-auth-chrome');
      if (chrome && chrome.parentNode) chrome.parentNode.removeChild(chrome);
    } catch (e) {}
  }

  function applyRoute() {
    if (isAuthPath()) {
      ensureAuthChrome();
      hideStockAuthMarks();
      hidePublicSignup();
    } else {
      teardownAuthChrome();
      ensureThemeToggle();
      scanOnce();
      ensurePhase1Fields();
    }
  }

  function pathName() {
    try {
      return location.pathname || '';
    } catch (e) {
      return '';
    }
  }

  function isItemFormPath() {
    var p = pathName();
    return p.indexOf('/items/') === 0 && p !== '/items/';
  }

  function isCustomerFormPath() {
    var p = pathName();
    return p.indexOf('/customers/') === 0 && p !== '/customers/';
  }

  function isItemListPath() {
    var p = pathName();
    return p === '/items' || p === '/items/';
  }

  function isCustomerListPath() {
    var p = pathName();
    return p === '/customers' || p === '/customers/';
  }

